-- Immutable resident generated bytes for one selected generation. The whole
-- committed corpus lives in memory as canonical LÖVE Data buffers: a batch is
-- confined, sized, and indexed privately before one non-yielding commit makes
-- it visible, and every reader borrows the same buffer instead of a serialized
-- copy. The owner knows logical generated paths, directory indexes, and its own
-- lifetime only: no job identity, ROM identity, family format, or eviction
-- policy belongs here, and no physical file is ever consulted or written.

local Errors = require("libs.errors.src.Errors")
local StorageErrors = require("libs.storage.src.errors")

-- Logical roots a generated entry may live under. Resident bytes are the
-- generated corpus only; saves, source bindings, and other version-scoped
-- files stay physical.
local GENERATED_ROOTS = { "data/generated", "assets/generated" }

local PATH_CODES = { PATH_INVALID = StorageErrors.CACHE_PATH_INVALID }

---@class ResidentCache.BlobRef
---@field sourceId string
---@field contentId string
---@field path string
---@field size integer
---@field data love.Data

---@class ResidentCache.BatchEntry
---@field path string
---@field data love.Data
---@field size integer
---@field sourceId string
---@field contentId string

---@class ResidentCache.PreparedBatch
---@field entries ResidentCache.BatchEntry[] sorted by path
---@field additions table<string, true>[]

---@class ResidentCache
---@field versionId string
---@field private _sourceId string
---@field private _entries table<string, ResidentCache.BlobRef>
---@field private _directories table<string, table<string, true>>
---@field private _closed boolean
local ResidentCache = {}
ResidentCache.__index = ResidentCache

---@param path string
---@return boolean
local function isGeneratedPath(path)
  if path:sub(-1) == "/" or path:find("\\", 1, true) ~= nil or path:find("\0", 1, true) ~= nil then
    return false
  end
  for _, root in ipairs(GENERATED_ROOTS) do
    if path:sub(1, #root + 1) == root .. "/" and #path > #root + 1 then
      return true
    end
  end
  return false
end

-- Confinement is the same rule the scoped filesystems use: normalized relative
-- components only, no alias that could address a committed entry twice.
---@param path string
---@return string
local function confinePath(path)
  assert(type(path) == "string" and path ~= "", "resident entry path is required")
  if path:find("\0", 1, true) then
    Errors.raise(PATH_CODES.PATH_INVALID, "path contains NUL", { path = path })
  end
  if path:sub(1, 1) == "/" or path:match("^%a:") then
    Errors.raise(PATH_CODES.PATH_INVALID, "path must be relative", { path = path })
  end
  for component in (path .. "/"):gmatch("(.-)/") do
    if component == "" or component == "." or component == ".." then
      Errors.raise(PATH_CODES.PATH_INVALID, "illegal path component: '" .. component .. "'", { path = path })
    end
  end
  if not isGeneratedPath(path) then
    Errors.raise(PATH_CODES.PATH_INVALID, "path is outside the generated roots", { path = path })
  end
  return path
end

---@param versionId string
---@param sourceId string opaque to storage; the generation identity of these bytes
---@return ResidentCache
function ResidentCache.new(versionId, sourceId)
  assert(type(versionId) == "string" and versionId ~= "", "resident cache requires its version id")
  assert(type(sourceId) == "string" and sourceId ~= "", "resident cache requires its source identity")
  return setmetatable({
    versionId = versionId,
    _sourceId = sourceId,
    _entries = {},
    _directories = {},
    _closed = false,
  }, ResidentCache)
end

---@return string
function ResidentCache:sourceId()
  return self._sourceId
end

---@param path string
---@return ResidentCache.BlobRef|nil
function ResidentCache:resolveAsset(path)
  if self._closed then
    return nil
  end
  return self._entries[path]
end

---@param path string
---@return love.Data|nil
function ResidentCache:readData(path)
  local reference = self:resolveAsset(path)
  if reference == nil then
    return nil
  end
  return reference.data
end

---@param prefix string
---@return string[] sortedPaths
function ResidentCache:paths(prefix)
  if self._closed then
    return {}
  end
  assert(type(prefix) == "string", "resident path prefix must be a string")
  local matched = {}
  for path in pairs(self._entries) do
    if prefix == "" or path:sub(1, #prefix) == prefix then
      matched[#matched + 1] = path
    end
  end
  table.sort(matched)
  return matched
end

-- Immediate children of a resident directory, as a diagnostic listing. Empty
-- when the directory holds nothing committed.
---@param directoryPath string
---@return string[] sortedNames
function ResidentCache:getDirectoryItems(directoryPath)
  if self._closed then
    return {}
  end
  local children = self._directories[directoryPath]
  if children == nil then
    return {}
  end
  local names = {}
  for name in pairs(children) do
    names[#names + 1] = name
  end
  table.sort(names)
  return names
end

---@param path string
---@param expectedType string?
---@return boolean
function ResidentCache:exists(path, expectedType)
  if self._closed then
    return false
  end
  if self._entries[path] ~= nil then
    return expectedType == nil or expectedType == "file"
  end
  if self._directories[path] ~= nil then
    return expectedType == nil or expectedType == "directory"
  end
  return false
end

---@param path string
---@return { path: string, type: string, size: integer }
function ResidentCache:getInfo(path)
  local reference = self:resolveAsset(path)
  if reference ~= nil then
    return { path = path, type = "file", size = reference.size }
  end
  if self._directories[path] ~= nil then
    return { path = path, type = "directory", size = 0 }
  end
  ---@type { path: string, type: string, size: integer }
  return nil
end

-- Every directory a committed path implies, deepest last: a file makes its own
-- parent chain reachable so listings and existence agree with the file map.
---@param path string
---@param additions table<string, true>
local function collectDirectories(path, additions)
  local parent = path:match("^(.*)/[^/]+$")
  while parent ~= nil and parent ~= "" do
    if additions[parent] then
      return
    end
    additions[parent] = true
    parent = parent:match("^(.*)/[^/]+$")
  end
end

-- Validate one whole batch into a private index. Nothing visible changes: a
-- violated path, size, or duplicate refuses the batch as a whole.
---@param entries ResidentCache.BatchEntry[]
---@return ResidentCache.PreparedBatch
function ResidentCache:prepare(entries)
  assert(not self._closed, "a closed resident cache accepts no new bytes")
  assert(type(entries) == "table", "resident preparation requires its entries")
  local prepared = {}
  local seen = {}
  local additions = {}
  for index, entry in ipairs(entries) do
    assert(type(entry) == "table", "resident entry must be a table")
    local path = confinePath(entry.path)
    assert(seen[path] == nil, "resident batch carries the same path twice: " .. path)
    seen[path] = true
    assert(entry.sourceId == self._sourceId, "resident entry source identity does not match this store: " .. path)
    assert(type(entry.contentId) == "string" and entry.contentId ~= "", "resident entry content id is required")
    local data = entry.data
    assert(type(data) == "userdata", "resident entry must own a Data buffer: " .. path)
    ---@cast data love.Data
    assert(type(data.getSize) == "function", "resident entry must own a Data buffer: " .. path)
    local size = data:getSize()
    assert(type(size) == "number" and size % 1 == 0 and size >= 0, "resident entry size is invalid: " .. path)
    assert(entry.size == size, "resident entry size contradicts its buffer: " .. path)
    prepared[index] = {
      path = path,
      data = data,
      size = size,
      sourceId = entry.sourceId,
      contentId = entry.contentId,
    }
    collectDirectories(path, additions)
  end
  table.sort(prepared, function(first, second)
    return first.path < second.path
  end)
  local ordered = {}
  for directory in pairs(additions) do
    ordered[#ordered + 1] = directory
  end
  table.sort(ordered)
  return { entries = prepared, additions = ordered }
end

-- Publish an already validated batch. No user code runs and nothing yields
-- between the two maps: readers observe the previous mapping or the new one.
---@param prepared ResidentCache.PreparedBatch
---@return nil published
function ResidentCache:commit(prepared)
  assert(not self._closed, "a closed resident cache accepts no new bytes")
  assert(type(prepared) == "table" and type(prepared.entries) == "table", "resident commit requires a prepared batch")
  for _, entry in ipairs(prepared.entries) do
    assert(entry.sourceId == self._sourceId, "prepared resident entry belongs to another store")
    self._entries[entry.path] = {
      sourceId = entry.sourceId,
      contentId = entry.contentId,
      path = entry.path,
      size = entry.size,
      data = entry.data,
    }
  end
  for _, directory in ipairs(prepared.additions) do
    if self._directories[directory] == nil then
      local children = {}
      local name = directory:match("([^/]+)$")
      assert(name ~= nil, "resident directory path has no component")
      local parent = directory:match("^(.*)/[^/]+$") or ""
      local siblings = self._directories[parent]
      if siblings == nil then
        siblings = {}
        self._directories[parent] = siblings
      end
      siblings[name] = true
      self._directories[directory] = children
    end
  end
  for _, entry in ipairs(prepared.entries) do
    local parent = entry.path:match("^(.*)/[^/]+$")
    local name = entry.path:match("([^/]+)$")
    assert(name ~= nil, "resident entry path has no component")
    local children = self._directories[parent or ""]
    if children ~= nil then
      children[name] = true
    end
  end
  return nil
end

-- Revoke new lookups. Borrowed buffers stay alive through their holders; the
-- index itself is dropped so a retired generation cannot be read again.
---@return nil
function ResidentCache:close()
  if self._closed then
    return nil
  end
  self._closed = true
  self._entries = {}
  self._directories = {}
  return nil
end

return ResidentCache
